    [Test,Timeout(1800000)]
    public void UnitAncestorsAndInactiveConfiguredMotorRootRetainFull699GeometryAndMeasureActualTruckCenteredCourseEnvelope()
    {
        var args=Environment.GetCommandLineArgs();string Required(string key){int index=Array.IndexOf(args,key);Assert.That(index>=0&&index+1<args.Length,Is.True,key);return args[index+1];}
        var type=Type.GetType("LWS.TruckDragonRiders.Editor.DragonRiderSaddleAuthoring, Assembly-CSharp-Editor",true);int fixtureAt=Array.IndexOf(args,"-tsRiderExportColdFixture");bool export=fixtureAt>=0;if(export)Assert.That(fixtureAt+1,Is.LessThan(args.Length));var method=type.GetMethod(export?"InspectAndExportTestOnlyMotorRootInfernoAfterFresh699Geometry":"InspectOwnedMotorRootInfernoGeometryAndActualCourseEnvelopeWithoutSavingAssets");object[] parameters=export?new object[]{Required("-tsRiderAllActionEvidence"),Required("-tsRiderPointwiseEvidence"),Required("-tsRiderStartupEvidence"),args[fixtureAt+1]}:new object[]{Required("-tsRiderAllActionEvidence"),Required("-tsRiderPointwiseEvidence"),Required("-tsRiderStartupEvidence")};var report=JsonUtility.FromJson<Report>((string)method.Invoke(null,parameters));if(export){var fixture=report.testOnlyColdFixture;Assert.That(fixture,Is.Not.Null);Assert.That(fixture.runtimeAdapterConfiguredUnawakened&&fixture.sameCandidatePassed699&&fixture.configuredInactive&&fixture.pristineAuthoredStagingRestoredForSerialization&&fixture.sourceBytesExact&&fixture.nwhClosureExact,Is.True);Assert.That(fixture.hostContextQualified||fixture.nativeRuntimeAwakeObserved,Is.False);Assert.That(fixture.materialPoints,Is.EqualTo(5));Assert.That(System.IO.File.Exists(fixture.prefab)&&System.IO.File.Exists(fixture.manifest),Is.True);}
        Assert.That(report.intervalControlsPassed&&report.sourceBytesExact&&report.nwhExact&&report.sceneBytesExact,Is.True);Assert.That(report.profiles.Length,Is.EqualTo(1));var row=report.profiles[0];Assert.That(row.failure,Is.Null.Or.Empty);Assert.That(row.species,Is.EqualTo("dragon-inferno"));Assert.That(row.status,Does.StartWith("DERIVED_SINGLE_OWNED_SIZE_NATIVE_GEOMETRY_PASSED"));Assert.That(row.existingAllActionSafeMounted&&row.ownedDefaultValidated&&row.originalDefaultControlPassed&&row.sourceMotionUnchanged,Is.True);
        Assert.That(row.motorRootConfiguredInactive&&row.nativeMotorParentRetained&&row.nativeUnitAncestors,Is.True);Assert.That(row.nativeRuntimeAwakeObserved,Is.False,"EditMode activation must never pretend to prove native runtime Awake");Assert.That(row.nativeActorCandidateScale,Is.EqualTo(Vector3.one));Assert.That(row.nativeMotorRootOriginalScale,Is.EqualTo(Vector3.one*5));Assert.That(Vector3.Distance(row.nativeMotorRootCandidateScale,Vector3.one*17),Is.LessThan(.00001f));Assert.That(Vector3.Distance(row.nativeDeckWorldDimensionsBefore,row.nativeDeckWorldDimensionsAfter),Is.LessThanOrEqualTo(.00001f));Assert.That(row.nativeScaleFactorBefore,Is.EqualTo(5));Assert.That(row.nativeScaleFactorAfter,Is.EqualTo(17).Within(.00001f));Assert.That(row.nativeSpeedNormalizationRequired,Is.True);Assert.That(row.nativeSpeedFieldsChanged,Is.False);Assert.That(row.nativeFlightPositionModifier,Is.GreaterThan(0));Assert.That(row.catalogFlightSpeed,Is.GreaterThan(0));Assert.That(row.nativeUntunedFlightTarget,Is.EqualTo(row.nativeFlightPositionModifier*row.nativeScaleFactorAfter).Within(.00001f));
        Assert.That(row.actualPoses,Is.EqualTo(699));Assert.That(row.invalidAnatomicalPoses,Is.Zero);Assert.That(row.unsafeExpandedPlanningMisses,Is.Zero);Assert.That(row.candidateSatPairs,Is.Zero);Assert.That(row.exactOriginalBoxAcceptance&&row.originalFootprintFits,Is.True);Assert.That(row.candidateWheelContactPoses,Is.EqualTo(699));Assert.That(row.actualCandidateSkinScaleError,Is.LessThan(.001f));Assert.That(row.maximumActualWheelGap,Is.LessThanOrEqualTo(.03f));
