        TestContext.WriteLine("ACTUAL_UNIT_ANCESTOR_MOTOR_ROOT_FULL699_GEOMETRY factor="+row.roundedCandidateFactor+" ScaleFactor="+row.nativeScaleFactorBefore+"->"+row.nativeScaleFactorAfter+" untunedNativeTarget="+row.nativeUntunedFlightTarget+" catalogWorldSpeed="+row.catalogFlightSpeed+" nominalActualRadius="+envelope.maximumNominalGateRadialExtent+" allAttitudeActualRadius="+envelope.maximumAnyAttitudeVertexRadius+" NOT_RUNTIME_AWAKE_MOVEMENT_CAB_COURSE_OR_CANONICAL_ACCEPTANCE");
    }
